<script setup>
import { computed, onMounted, ref } from 'vue'
import { supabase } from '../lib/supabase'

const loading=ref(true),savingDate=ref(''),editing=ref(false),error=ref(''),message=ref(''),profiles=ref([]),schedule=ref(new Map()),drafts=ref(new Map()),editingDays=ref(new Set()),month=ref(firstOfMonth(new Date())),editWeekStart=ref(startOfWeek(new Date()))
const monthLabel=new Intl.DateTimeFormat('sl-SI',{month:'long',year:'numeric'}),dateLabel=new Intl.DateTimeFormat('sl-SI',{day:'numeric',month:'long',year:'numeric'}),weekdayLabel=new Intl.DateTimeFormat('sl-SI',{weekday:'long'})
function key(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function firstOfMonth(date){return new Date(date.getFullYear(),date.getMonth(),1)}
function startOfWeek(date){const copy=new Date(date),offset=(copy.getDay()+6)%7;copy.setDate(copy.getDate()-offset);copy.setHours(0,0,0,0);return copy}
function addDays(date,number){const copy=new Date(date);copy.setDate(copy.getDate()+number);return copy}
function emptyDay(date){return{work_date:key(date),sale_start:'08:00',sale_end:'17:00',is_closed:false,workers:[]}}
function dayDetails(date){const workDate=key(date),planned=schedule.value.get(workDate),draft=drafts.value.get(workDate);return{...emptyDay(date),...(planned||{}),...(draft||{}),date,planned:Boolean(planned),isWeekend:[0,6].includes(date.getDay()),isFutureOrToday:date>=startOfToday(),isEditable:!planned||editingDays.value.has(workDate)}}
function startOfToday(){const today=new Date();today.setHours(0,0,0,0);return today}
const allDays=computed(()=>{const count=new Date(month.value.getFullYear(),month.value.getMonth()+1,0).getDate();return Array.from({length:count},(_,index)=>dayDetails(addDays(month.value,index)))})
const plannedDays=computed(()=>allDays.value.filter(day=>day.planned))
const editDays=computed(()=>Array.from({length:7},(_,index)=>dayDetails(addDays(editWeekStart.value,index))))
function formatTime(value){return value?.slice(0,5).replace(':','.')}
function workerNames(day){return day.workers.map(id=>profiles.value.find(profile=>profile.id===id)?.full_name||'Brez imena').join(', ')}
function setEditing(next){editing.value=next;if(next)editingDays.value=new Set()}
async function load(){loading.value=true;error.value='';try{const monthFirst=key(month.value),monthLast=key(new Date(month.value.getFullYear(),month.value.getMonth()+1,0)),weekFirst=key(editWeekStart.value),weekLast=key(addDays(editWeekStart.value,6)),first=monthFirst<weekFirst?monthFirst:weekFirst,last=monthLast>weekLast?monthLast:weekLast;const[profilesResult,schedulesResult,workersResult]=await Promise.all([supabase.from('profiles').select('id,full_name').order('full_name'),supabase.from('work_schedules').select('work_date,sale_start,sale_end,is_closed').gte('work_date',first).lte('work_date',last),supabase.from('work_schedule_workers').select('work_date,profile_id').gte('work_date',first).lte('work_date',last)]);if(profilesResult.error||schedulesResult.error||workersResult.error)throw profilesResult.error||schedulesResult.error||workersResult.error;profiles.value=profilesResult.data;const workersByDate=new Map();for(const worker of workersResult.data)workersByDate.set(worker.work_date,[...(workersByDate.get(worker.work_date)||[]),worker.profile_id]);schedule.value=new Map(schedulesResult.data.map(day=>[day.work_date,{...day,workers:workersByDate.get(day.work_date)||[]}]))}catch{error.value='Urnika ni bilo mogoče naložiti. Preverite, ali je bila Supabase migracija zagnana.'}finally{loading.value=false}}
function changeMonth(amount){month.value=new Date(month.value.getFullYear(),month.value.getMonth()+amount,1);load()}
function changeWeek(amount){editWeekStart.value=addDays(editWeekStart.value,amount);load()}
function updateDay(day){drafts.value=new Map(drafts.value).set(day.work_date,{...day})}
function unlockDay(day){editingDays.value=new Set(editingDays.value).add(day.work_date)}
function addWorker(day,event){const id=event.target.value;if(id&&!day.workers.includes(id)){day.workers=[...day.workers,id];updateDay(day)}event.target.value=''}
function removeWorker(day,id){day.workers=day.workers.filter(worker=>worker!==id);updateDay(day)}
async function saveDay(day){savingDate.value=day.work_date;error.value='';message.value='';try{const{error:scheduleError}=await supabase.from('work_schedules').upsert({work_date:day.work_date,is_closed:day.is_closed,sale_start:day.is_closed?null:day.sale_start,sale_end:day.is_closed?null:day.sale_end});if(scheduleError)throw scheduleError;const{error:deleteError}=await supabase.from('work_schedule_workers').delete().eq('work_date',day.work_date);if(deleteError)throw deleteError;if(!day.is_closed&&day.workers.length){const{error:workersError}=await supabase.from('work_schedule_workers').insert(day.workers.map(profile_id=>({work_date:day.work_date,profile_id})));if(workersError)throw workersError}schedule.value=new Map(schedule.value).set(day.work_date,{...day});drafts.value=new Map([...drafts.value].filter(([workDate])=>workDate!==day.work_date));editingDays.value=new Set([...editingDays.value].filter(workDate=>workDate!==day.work_date));message.value=`Urnik za ${dateLabel.format(day.date)} je shranjen.`}catch{error.value='Urnika ni bilo mogoče shraniti. Preverite ure prodaje in poskusite znova.'}finally{savingDate.value=''}}
onMounted(load)
</script>
<template><section class="page schedule-page"><header class="schedule-heading"><div><p class="eyebrow">Sladki kot</p><h1>Urnik dela</h1><p class="muted">Razpored zaposlenih po dnevih</p></div><button class="secondary schedule-edit" @click="setEditing(!editing)">{{editing?'Pregled':'Urejaj'}}</button></header><nav v-if="!editing" class="schedule-navigation"><button class="secondary" @click="changeMonth(-1)">Prejšnji mesec</button><strong>{{monthLabel.format(month)}}</strong><button class="secondary" @click="changeMonth(1)">Naslednji mesec</button></nav><nav v-else class="schedule-navigation"><button class="secondary" @click="changeWeek(-7)">Prejšnji teden</button><strong>{{dateLabel.format(editWeekStart)}}–{{dateLabel.format(addDays(editWeekStart,6))}}</strong><button class="secondary" @click="changeWeek(7)">Naslednji teden</button></nav><p v-if="error" class="error">{{error}}</p><p v-if="message" class="success">{{message}}</p><div v-if="loading" class="center-state">Nalagam urnik …</div><div v-else-if="!editing&&!plannedDays.length" class="schedule-empty">Za ta mesec še ni načrtovanih dni.</div><div v-else-if="!editing" class="schedule-overview"><article v-for="day in plannedDays" :key="day.work_date" class="schedule-overview-day" :class="{'schedule-overview-day--weekend':day.isWeekend,'schedule-overview-day--future':day.isFutureOrToday}"><time :datetime="day.work_date">{{dateLabel.format(day.date)}}</time><strong v-if="day.is_closed">Zaprto</strong><span v-else class="schedule-workers-display">{{workerNames(day)||'Brez načrtovanih zaposlenih'}}</span></article></div><div v-else class="schedule-days"><article v-for="day in editDays" :key="day.work_date" class="schedule-day" :class="{'schedule-day--saved':day.planned&&!day.isEditable,'schedule-day--weekend':day.isWeekend}"><header><div><p class="eyebrow">{{weekdayLabel.format(day.date)}}</p><h2>{{dateLabel.format(day.date)}}</h2></div><button v-if="day.planned&&!day.isEditable" class="schedule-pencil" type="button" aria-label="Uredi dan" title="Uredi dan" @click="unlockDay(day)">✎</button></header><template v-if="day.isEditable"><label class="schedule-closed"><input v-model="day.is_closed" type="checkbox" @change="updateDay(day)" /> Zaprto</label><template v-if="!day.is_closed"><label class="schedule-worker-select">Kdo dela<select @change="addWorker(day,$event)"><option value="">Dodaj zaposlenega</option><option v-for="profile in profiles.filter(profile=>!day.workers.includes(profile.id))" :key="profile.id" :value="profile.id">{{profile.full_name||'Brez imena'}}</option></select></label><div v-if="day.workers.length" class="schedule-worker-chips"><span v-for="id in day.workers" :key="id">{{profiles.find(profile=>profile.id===id)?.full_name||'Brez imena'}}<button type="button" :aria-label="`Odstrani ${profiles.find(profile=>profile.id===id)?.full_name||'zaposlenega'}`" @click="removeWorker(day,id)">×</button></span></div></template><p v-else class="muted">Sladki kot je ta dan zaprt.</p><button :disabled="Boolean(savingDate)" @click="saveDay(day)">{{savingDate===day.work_date?'Shranjujem …':'Shrani dan'}}</button></template><template v-else><strong v-if="day.is_closed">Zaprto</strong><span v-else class="schedule-workers-display">{{workerNames(day)||'Brez načrtovanih zaposlenih'}}</span></template></article></div></section></template>
